Suppose you want to add two tuples, element by element. You could use two
nested lambdas to expand the two tuples in succession, but this would be a bit
awkward. Instead, you can use ` std::make_index_sequence ` to get the tuple
indices, then use the indices in a pattern that accesses the elements of both
tuples element by element. Here is the code:



    template<typename T>
    auto
    tuple_add(const T &a, const T&b)
    {
      return [&a, &b]<std::size_t ...I>(std::index_sequence<I...>) {
        return std::tuple(get<I>(a) + get<I>(b)...);
      }(std::make_index_sequence<std::tuple_size_v<T>>{});
    }

    int
    main()
    {
      auto t = std::tuple(1, 2U, 4.0);
      t = tuple_add(t, tuple_mult(10, t));
      std::cout << get<0>(t) << " "
                << get<1>(t) << " "
                << get<2>(t) << std::endl;
      // prints:
