    let i = 0;
    const a = {
      [`foo${++i}`]: i,
      [`foo${++i}`]: i,
      [`foo${++i}`]: i,
    };

    console.log(a.foo1); // 1
    console.log(a.foo2); // 2
    console.log(a.foo3); // 3

