Using-declaration introduces a member of a base class into the derived class
definition, such as to expose a protected member of base as public member of
derived. In this case,  nested-name-specifier  must name a base class of the
one being defined. If the name is the name of an overloaded member function of
the base class, all base class member functions with that name are introduced.
If the derived class already has a member with the same name, parameter list,
and qualifications, the derived class member hides or overrides (doesn't
conflict with) the member that is introduced from the base class.

Run this code



    #include <iostream>
     
    struct B
    {
        virtual void f(int) { [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "B::f\n"; }
        void g(char)        { [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "B::g\n"; }
        void h(int)         { [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "B::h\n"; }
    protected:
        int m; // B::m is protected
        typedef int value_type;
    };
     
    struct D : B
    {
        using B::m;          // D::m is public
        using B::value_type; // D::value_type is public
     
        using B::f;
        void f(int) override { [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "D::f\n"; } // D::f(int) overrides B::f(int)
     
        using B::g;
        void g(int) { [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "D::g\n"; } // both g(int) and g(char) are visible
     
        using B::h;
        void h(int) { [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "D::h\n"; } // D::h(int) hides B::h(int)
    };
     
    int main()
    {
        D d;
        B& b = d;
     
    //  b.m = 2;  // Error: B::m is protected
        d.m = 1;  // protected B::m is accessible as public D::m
     
        b.f(1);   // calls derived f()
        d.f(1);   // calls derived f()
        [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "----------\n";
     
        d.g(1);   // calls derived g(int)
        d.g('a'); // calls base g(char), exposed via using B::g;
        [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "----------\n";
     
        b.h(1);   // calls base h()
        d.h(1);   // calls derived h()
    }

